scwin.gExcelTp = "1";
scwin.pageSize = 50; // 페이지 size
scwin.totalCnt = 0; // 전체 row
scwin.pageNoCnt = 10; // page 번호 개수
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
// 화면 리사이징

scwin.gDepCd;
scwin.gUpDepCd;
scwin.gEmpNo;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gScnNm;
scwin.gKeyword;

// DisclosureSearchAppImpl.java 에서 사용중. vScrenID바꾸지 마세요 20170421
scwin.gUsrId = js_id;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await $c.session.sessionCheck();
        grd_Grid_excel.hide();
        mgrd_Grid_excel.hide();
        panel_scn.hide();
        panel_combo.hide();
        mgrd_Grid.hide();
        txb_FssUnqNo.hide();
        txb_indTpCd.hide();
        txb_idxIndCd.hide();
        grd_isurList.hide();

        // KBoY 2017-12-06
        // 마이그레이션때 반영함. 검색엔진에서는 제외 2018.01.24
        // showObj(panel_myForm, false);

        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        $c.stf.comboCbDataSet(cmb_PerPage);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_Dscl_Cond",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Dscl_Cond=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        $c.cm.fn_com_isur_all(txb_isur_cd, txb_com_abbrv); // 2018.02.09 전체로 변경 SrM-000164107

        await scwin.checkCond();
        await scwin.myFormNmList();
        showload.style.display = "none";
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
