/**
 * @method
 * @name cmb_PerPage_OnCloseUp
 * @description cmb Per Page On Close Up 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_PerPage_OnCloseUp = async function() {
    try {
        const vPerPage = $c.cp.valueOfIndex(cmb_PerPage, "VALUE", cmb_PerPage.getSelectedIndex());
        scwin.pageSize = vPerPage;
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003.cmb_PerPage_OnCloseUp" });
