};

/**
 * @method
 * @name dts_DsclList_OnLoadError
 * @description dts_DsclList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadError = async function() {
    try {
        await $c.win.alert("OnLoadError => " + dts_DsclList.errorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003.dts_DsclList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DsclList_OnLoadCompleted
 * @description dts_DsclList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadCompleted = async function(rowcount) {
    try {
        showload.style.display = "none";

        // 채권일경우 상장 제외 20170310
        if (rdo_MKT_ID.getValue() === "4") {
            $c.cm.setColumnProp(grd_Grid, "LIST_STAT_ID", 'Show', false);
            $c.cm.setColumnProp(grd_Grid, "COM_ABBRV", 'color', "Black");
        } else {
            $c.cm.setColumnProp(grd_Grid, "LIST_STAT_ID", 'Show', true);
        }
        if (dts_DsclList.errorMsg) {
            await $c.win.alert("OnLoadCompleted => " + dts_DsclList.errorMsg);
        } else {
            /*
            //수정해야될 부분
            //데이터가 로드 되면 다음 내용을 처리 하도록 한다.
            //최초 조회인 경우 전체 row cnt를 구한다.
            if (vCurrPageNo == 0){
            	vCurrPageNo = 1;
            	totalCnt = dts_DsclList.NameString(0,"TOTALCNT");
            }
             */
            if (scwin.pageSize !== '0') {
                if (scwin.vCurrPageNo === 0) {
                    scwin.vCurrPageNo = 1;
                    scwin.totalCnt = dts_DsclList.getCellData(0, "TOTALCNT");
                }
            } else {
                scwin.totalCnt = rowcount;
            }
            // alert(pageNoCnt +", "+pageSize+", "+totalCnt);
            // 페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
            $c.stf.FillGridHeader(scwin.pageNoCnt, scwin.pageSize, scwin.totalCnt, panel_page, 743);
        }

        // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        btn_Search.setDisabled(false);
        btn_Search.setBackgroundImage("../img/btn_select.gif");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003.dts_DsclList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_scn_list_OnLoadCompleted
 * @description dts_scn_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_scn_list_OnLoadCompleted = function(rowcount) {
    try {
        let combo_text = "";
        for (let i = 0; i <= dts_scn_list.getRowCount() - 1; i++) {
            combo_text += $c.cp.valueOfIndex(cmb_scn_list, "TEXT", i) + ",";
        }
        panel_combo.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='16' width='100%'>" + "    <tr>" + "        <td align='left'  nowrap style='font-size__9pt; font-family:굴림;'>" + $c.ut.replaceAll(combo_text.substring(0, combo_text.lastIndexOf(',')), " ", "") + "</td>";
        "    </tr>" + "</table>";

        // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        // btn_Search.disabled = false;
        // btn_Search.src = "../img/btn_select.gif";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15003.dts_scn_list_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_emp_OnLoadCompleted
 * @description dts_emp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
