 */
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    // setObjectValue(cmb_EmpList, js_emp_no) ;

};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "" || scwin.gDepCd === "UPTEAM") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "UPTEAM" ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15003.dts_emp_OnFilter" });
    }
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description dts_dep 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    try {
        if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
            $c.stf.copyDataSet(dts_dep, dts_dep1);
            scwin.addDsclTeamAll(rowcount);
            //        setObjectValue(cmb_TeamList, 'UPTEAM') ;

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15003.dts_dep_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_DsclList_excel_OnLoadCompleted
 * @description dts_DsclList_excel 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_excel_OnLoadCompleted = async function(rowcount) {
    try {
        showload.style.display = "none";
        if (scwin.gExcelTp === "1") {
            // 채권일경우 상장 제외 20170310
            if (rdo_MKT_ID.getValue() === "4") {
                $c.cm.setColumnProp(grd_Grid_excel, "LIST_STAT_ID", 'Show', false);
                $c.cm.setColumnProp(grd_Grid_excel, "COM_ABBRV", 'color', "Black");
            }
            $c.data.downloadGridViewExcel(grd_Grid_excel, {fileName: "공시상세검색  목록", type: "8"});
        } else {
            const responseCode = dts_DsclList_excel.getCellData(1, "VALUE");
            const inside_email = dts_DsclList_excel.getCellData(1, "TEXT");
            if (responseCode === "200") {
                await $c.win.alert("1만건 이상은 메일로 제공합니다.\n엑셀저장이 완료되면 등록된 이메일(" + inside_email + ")로 엑셀파일 링크가 전송됩니다.\n(5만건 기준 약 1분 소요).");
            } else {
                await $c.win.alert("엑셀저장에 실패하였습니다. [" + responseCode + "]");
            }
        }

        // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        btn_Excel.setDisabled(false);
        btn_Excel.setBackgroundImage("../img/btn_excelsave.gif");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003.dts_DsclList_excel_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "DOC_TITLE") {
            await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF15003.xml');
        } else if (colid === "ACPT_DDTM") {
            $c.stf.openKindList();
        } else if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name mgrd_Grid_OnLButtonDblClk
 * @description mgrd Grid On LButton Dbl Clk 처리
 * @param {*} type type
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} x x
 * @param {*} y y
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.mgrd_Grid_OnLButtonDblClk = async function(type, row, colid, x, y) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "DOC_TITLE") {
            await $c.stf.openDisclViewer(scwin.gAcptNo, "R");
        } else if (colid === "ACPT_DDTM") {
            $c.stf.openDisclAllList();
        } else if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15003.mgrd_Grid_OnLButtonDblClk" });
    }
};

