        dts_Dscl_Cond.Reset();
        txb_rsn_cnt.setValue(dts_Dscl_Cond.getRowCount());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15003.rdo_MKT_ID_onselchange" });
    }
};

