    try {
        let url = "/dsclsrch/HELP_SEARCHTYPE.html";
        let winTitle = "본문검색 키워드 도움말";
        await $c.frame.CreateFrame("HELP_KEY", url, winTitle, 10, 10, 500, 300, "window", 0, 0, true);
        /*
