/**
 * @method
 * @name excelDownload
 * @description 공시상세검색    엑셀다운로드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDownload = async function() {
    let vKeyword = txb_keyword.getValue();
    if (vKeyword.length > 0) {
        $c.stf.doLogSave('ULDSTF15003.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(mgrd_Grid_excel, {fileName: "공시상세검색 목록(본문내용)", type: "8"});
    } else {
        showload.style.display = "";

        // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        btn_Excel.setDisabled(true);
        btn_Excel.setBackgroundImage("../img/btn_excelsave_d.gif");
        let url = "";

        // 1만건 이상인 경우 메일로 전송
        if (scwin.totalCnt >= 10000) {
            scwin.gExcelTp = "2";
            url = "/DsclSearchAll.do?method=listDsclDtlSrchAllExcel";
        } else {
            scwin.gExcelTp = "1";
        }
