/**
 * @method
 * @name clear
 * @description 종목선택 데이타 clear 처리
 * @returns {void}
 * @hidden N
 */
scwin.clear = function() {
    dts_isurList.removeAll();
    txb_indTpCd.setValue("");
    txb_idxIndCd.setValue("");
    scwin.gStrIusrCd = "";
};

/**
 * @method
 * @name checkComNmCond
 * @description 법인명이 있고 특정 다른 조건을 선택할때 메세지
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkComNmCond = async function() {
    let vIsurCd = txb_isur_cd.getValue();
    if (vIsurCd !== '') {
        await $c.win.alert("해당항목 선택시 법인코드(명)의 조건값이  초기화 됩니다.");
        txb_isur_cd.setValue('');
        txb_com_abbrv.setValue('');
        scwin.clear();
        return;
    }
};

/**
 * @method
 * @name checkCond
 * @description 공시상세  목록검색 조건체크  : 사용자 클릭
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCond = async function() {
    let vIsurCd = txb_isur_cd.getValue();
    const vFssUnqNm = txb_FssUnqNm.getValue();
    const vFormCd = txb_FormCd.getValue();
    const vFormNm = txb_FormNm.getValue();
    const vRsnclssCnt = txb_rsn_cnt.getValue();
    let vKeyword = txb_keyword.getValue();

    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }

    // 보고서코그 체크
    if (vFormCd.length > 0 && vFormCd.length !== 5) {
        await $c.win.alert("보고서코드 5자리를 입력하십시오.");
        txb_FormCd.focus();
        return;
    }
    // 언어구분 체크
    if (scwin.getChkValue(chb_kor_yn) === 0 && scwin.getChkValue(chb_eng_yn) === 0) {
        await $c.win.alert("언어구분은 한개이상 선택하십시오.");
        chb_kor_yn.focus();
        return;
    }

    // 제출유형 체크
    if (scwin.getChkValue(chb_main_yn) === 0 && scwin.getChkValue(chb_atch_yn) === 0) {
        await $c.win.alert("제출유형은 한개이상 선택하십시오.");
        chb_main_yn.focus();
        return;
    }
    if (await scwin.chkAttchKeyword() === false) {
        return;
    }

    // 공시사유분류
    let sRsnClssCdList = "";
    let sFormUpclssCd;
    let sRsnClssCd;
    for (let i = 1; i <= dts_Dscl_Cond.getRowCount(); i++) {
        sFormUpclssCd = dts_Dscl_Cond.getCellData(i, "FORM_UPCLSS_CD");
        sRsnClssCd = dts_Dscl_Cond.getCellData(i, "RSN_CLSS_CD");
        if (sRsnClssCd !== "000") {
            sRsnClssCdList += (sFormUpclssCd + sRsnClssCd + ",");
        }
    }

    // 맨뒤에 ", " 제거 하기
    scwin.gRsnClssCdList = sRsnClssCdList.substr(0, sRsnClssCdList.length - 1);
    scwin.gDepCd = cmb_TeamList.getValue();
    scwin.gEmpNo = cmb_EmpList.getValue();
    if (scwin.gDepCd === "UPTEAM" && js_dep_cd.substr(2, 4) === '00') {
        scwin.gUpDepCd = js_dep_cd;
    }
    scwin.setStrIusrCd(); // gStrIusrCd 설정

    await scwin.search();
};

/**
 * @method
 * @name setStrIusrCd
 * @description set Str Iusr Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.setStrIusrCd = function() {
    scwin.gStrIusrCd = "";
    // 지수종목 선택시
    if (txb_indTpCd.getValue().length <= 0 && txb_idxIndCd.getValue().length <= 0 && txb_isur_cd.getValue().length <= 0) {
        for (let i = 1; i <= dts_isurList.getRowCount(); i++) {
            const asNm = dts_isurList.getCellData(i, "ISUR_CD");
            if (asNm !== "") {
                if (i === 1) {
                    scwin.gStrIusrCd = asNm;
                } else {
                    scwin.gStrIusrCd = scwin.gStrIusrCd + "," + asNm;
                }
            }
        }
    }
};

/**
 * @method
 * @name search
 * @description 공시상세   목록검색 : 사용자 클릭
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const edt_FromDate_year = edt_FromDate.getValue().substr(0, 4);
    const edt_FromDate_month = edt_FromDate.getValue().substr(4, 2) - 1;
    const edt_FromDate_day = edt_FromDate.getValue().substr(6, 2);
    const edt_FromDate_Date = new Date(edt_FromDate_year, edt_FromDate_month, edt_FromDate_day);
    const edt_ToDate_year = edt_ToDate.getValue().substr(0, 4);
    const edt_ToDate_month = edt_ToDate.getValue().substr(4, 2) - 1;
    const edt_ToDate_day = edt_ToDate.getValue().substr(6, 2);
    const edt_ToDate_Date = new Date(edt_ToDate_year, edt_ToDate_month, edt_ToDate_day);

    // 3년 이상의 기간은 검색 할 수 없다
    const date_result = (Date.parse(edt_ToDate_Date) - Date.parse(edt_FromDate_Date)) / (1000 * 60 * 60 * 24);
    if (date_result > 1096) {
        await $c.win.alert("검색기간은 3년 이상을 초과 할 수 없습니다.");
        return;
    }

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_Search.setDisabled(true);
    btn_Search.setBackgroundImage("../img/btn_select_d.gif");
    scwin.vCurrPageNo = 0;
    dts_DsclList_excel.removeAll();
    scwin.checkMyForm();

    // 공시본문검색은 채권해제법인제외 조건을 선택하지 못하게 한다.
    // 검색엔진 테이블에 채권공시법인여부 칼럼이 없어서..
    if (txb_keyword.getValue() !== "") {
        if (rdo_MKT_ID.getValue() === '4') {
            chb_ListStatCd.setValue(0);
        }
    }
    let url = "";
    let url_cond = "&ISUR_CD=" + txb_isur_cd.getValue() + "&FROM_DATE=" + edt_FromDate.getValue() + "&TO_DATE=" + edt_ToDate.getValue() + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + scwin.gUpDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&BYPASS_YN=" + scwin.getChkValue(chb_ByPass) + "&FORM_CD=" + txb_FormCd.getValue() + "&FORM_NM=" + txb_FormNm.getValue() + "&KEYWORD=" + $c.ut.replaceAll(txb_keyword.getValue(), "&", "＆") + "&FSS_UNQ_NO=" + txb_FssUnqNo.getValue() + "&FSS_UNQ_NM=" + txb_FssUnqNm.getValue() + "&ACNTCLS_MM=" + cmb_month.getValue() + "&IND_TP=" + cmb_IndTp.getValue() + "&KOR_YN=" + scwin.getChkValue(chb_kor_yn) + "&ENG_YN=" + scwin.getChkValue(chb_eng_yn) + "&LD_MKT_TP=" + rdo_MKT_ID.getValue() + "&RSN_CLSS_CD_LIST=" + scwin.gRsnClssCdList + "&MAIN_YN=" + scwin.getChkValue(chb_main_yn) + "&ATCH_YN=" + scwin.getChkValue(chb_atch_yn) + "&DEP_TP=" + scwin.getChkValue(chb_dep_tp) + "&BASIS_TP=" + cmb_Basis.getValue() + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + 'ULDSTF15003.xml' + "&MYFORM_LIST_GRP=" + cmb_myFormNmList.getValue() + "&USR_ID=" + scwin.gUsrId + "&IDX_ID=" + txb_idxIndCd.getValue() + "&STR_ISUR_CD=" + scwin.gStrIusrCd + "&SUBCOM_YN=" + scwin.getChkValue(chk_branch) + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    scwin.gKeyword = txb_keyword.getValue();
    if (scwin.gKeyword.length > 0) {
        // 본문검색 키워드가있을때
        let iOpCnt = 0;
        if (scwin.gKeyword.indexOf("&") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (scwin.gKeyword.indexOf("|") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (scwin.gKeyword.indexOf("!") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (iOpCnt > 1) {
            await $c.win.alert("본문검색 키워드는 한 개만 사용할 수 있습니다.");
            txb_keyword.focus();
            return;
        }
        if (scwin.pageSize === 0) {
            await $c.win.alert("공시본문내용으로 검색할 경우에는 한페이지당 보여주는 갯수를 '전체'로 사용할 수 없습니다.");
            cmb_PerPage.setValue("50");
            cmb_PerPage.focus();
            return;
        }
        mgrd_Grid.show("");
        grd_Grid.hide();

        // 1. 검색 건수부터 조회한다.
        url = "/DsclSearchAll.do?method=cntDsclDtlSrchEngineAll" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=SCN_CNTSTAT_OUT";

        // alert("본문검색 카운트: "+url + url_cond);
        dts_scn_list.DataID = encodeURI(url + url_cond);
        dts_scn_list.reset();
        const vScnCur = dts_scn_list.getCellData(dts_scn_list.getRowCount(), "SCN_CUR");
        // alert(dts_scn_list.CountRow +", "+vScnCur);

        if (dts_scn_list.getRowCount() > 0) {
            // 2.  Docruzer으로 검색
            url = "/DsclSearchAll.do?method=pagingDsclDtlSrchEngineAll" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
            url_cond += "&SCN_NM=" + vScnCur;
            dts_DsclList.DataID = encodeURI(url + url_cond);
            dts_DsclList.reset();
            panel_scn.show("");
            panel_combo.show("");
            mgrd_Grid.show("");
            grd_Grid.hide();
        } else {
            // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
            btn_Search.setDisabled(false);
            btn_Search.setBackgroundImage("../img/btn_select.gif");
            scwin.vCurrPageNo = 0;
            dts_DsclList_excel.removeAll();
            dts_DsclList.removeAll();
            // showObj(mgrd_Grid, true);
            // showObj(grd_Grid, false);
        }
    } else {
        // 본문검색 키워드가 없을때 ... 일반 DB검색
        url = "/DsclSearchAll.do?method=pagingDsclDtlSrchAll" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
        dts_DsclList.DataID = encodeURI(url + url_cond);
        dts_DsclList.reset();
        panel_scn.hide();
        panel_combo.hide();
        mgrd_Grid.hide();
        grd_Grid.show("");
    }
};

