/**
 * @method
 * @name resetParam
 * @description 취소버튼을 눌렀을 경우
 * @returns {void}
 * @hidden N
 */
scwin.resetParam = function() {
    vCurrDate = $c.ut.cGetToday("yyyymmdd"); // 현재날짜

    rdo_MKT_ID.setValue('9');

    // 채권일 경우 채권상장폐지여부 제외 항목으로 보이게끔 수정 20170310
    if (rdo_MKT_ID.getValue() === '4') {
        label_3.hide();
        label_24.show("");
        scwin.setChkValue(chb_ListStatCd, "1");
    } else {
        label_3.show("");
        label_24.hide();
        scwin.setChkValue(chb_ListStatCd, false);
    }
    txb_isur_cd.setValue("");
    txb_com_abbrv.setValue("");
    edt_FromDate.setValue(vCurrDate);
    edt_ToDate.setValue(vCurrDate);
    cmb_PeriodTp.setValue(-1);
    cmb_EmpList.setValue("");
    // setChkValue(chb_ListStatCd, false);
    scwin.setChkValue(chb_Last, false);
    scwin.setChkValue(chb_ByPass, false);
    txb_FormCd.setValue("");
    txb_FormNm.setValue("");
    txb_keyword.setValue("");
    txb_FssUnqNo.setValue("");
    txb_FssUnqNm.setValue("");
    cmb_month.setValue("");
    cmb_IndTp.setValue("");
    scwin.setChkValue(chb_kor_yn, true);
    scwin.setChkValue(chb_eng_yn, true);
    scwin.setChkValue(chb_main_yn, true);
    scwin.setChkValue(chb_atch_yn, true);
    scwin.setChkValue(chb_dep_tp, true);
    cmb_Basis.setValue("2");
    cmb_PerPage.setValue("50");
    txb_rsn_cnt.setValue("");
    dts_Dscl_Cond.removeAll();
    scwin.gRsnClssCdList = "";
    // 종목선택추가시 초기화해줄 부분
    dts_isurList.removeAll();
    txb_indTpCd.setValue("");
    txb_idxIndCd.setValue("");
    scwin.gStrIusrCd = "";
    scwin.setChkValue(chk_branch, false);
};

/**
 * @method
 * @name addDsclTeamAll
 * @description 공시팀 전체 목록에 추가
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM');
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    dts_dep.setBroadcast(false);
    for (let i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE"));
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.setBroadcast(true, true);
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE"));
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};

/**
 * @method
 * @name chkAttchKeyword
 * @description 첨부서류만 선택하고 본문검색을 하고자할때 알림.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkAttchKeyword = async function() {
    let vKeyword = txb_keyword.getValue();
    if (vKeyword.length > 0) {
        if (scwin.getChkValue(chb_main_yn) === 0 &&
            scwin.getChkValue(chb_atch_yn) === 1) {
            await $c.win.alert('첨부서류만 선택한 후에는 공시본문내용 검색기능을 사용 할 수 없습니다.\n공시본문에서만 내용검색이 가능합니다.');
            txb_keyword.focus();
            return false;
        }
    }
};

/**
 * @method
 * @name checkMyForm
 * @description 2017-11-30 KBoY 사용자서식그룹이 선택되어 있으면 서식코드 검색 내용 삭제.
 * @returns {void}
 * @hidden N
 */
scwin.checkMyForm = function() {
    if (cmb_myFormNmList.getSelectedIndex() === 1) {
        txb_FormCd.setValue('');
        txb_FormNm.setValue('');
    }
};
